class EstablecimientoCtrl{static $inject=["mainService","commonService","toastService","modalService","nombreModal"];constructor(_mS,_commonSvc,_tS,_modalSvc,_nombreModalConst){this._mS=_mS,this._commonSvc=_commonSvc,this._tS=_tS,this._modalSvc=_modalSvc,this._nombreModalConst=_nombreModalConst,this.dataSearch={pageIndex:1,pageSize:10,typeList:1},this.maxSize=5,this.totalRecords=0,this.recordsQuantity=[5,10,25,50],this.establecimientos=[]}$onInit(){this.getEstablecimientos()}async getEstablecimientos(){try{showLoader(),await this._mS.getData("get","/Establecimiento/Get?json="+JSON.stringify(this.dataSearch)).then(response=>{"0"!==response.code?this.establecimientos=JSON.parse(response.payload)||[]:console.warn(response.message)})}catch(error){hideLoader(),console.trace(error)}finally{hideLoader()}}async openModalNew(){let{MODAL_CTRL:MODAL_CTRL,MODAL_NUEVO:MODAL_NUEVO}=this._nombreModalConst.establecimiento,controller=(await import("./../../modal/"+MODAL_CTRL))[MODAL_NUEVO.controller],template=MODAL_NUEVO.template,params={tipoRegistro:"N"};this.openModal(controller,template,params)}async openModalEdit(params){let{MODAL_CTRL:MODAL_CTRL,MODAL_EDIT:MODAL_EDIT}=this._nombreModalConst.establecimiento,controller=(await import("./../../modal/"+MODAL_CTRL))[MODAL_EDIT.controller],template=MODAL_EDIT.template;params.tipoRegistro="E",this.openModal(controller,template,params)}async openModalConfig(params){let{MODAL_CTRL:MODAL_CTRL,MODAL_CONFIG:MODAL_CONFIG}=this._nombreModalConst.establecimiento,controller=(await import("./../../modal/"+MODAL_CTRL))[MODAL_CONFIG.controller],template=MODAL_CONFIG.template;this.openModal(controller,template,params,"xl")}openModal(controller,template,params,size="lg"){this._modalSvc.openModalCustom({controller:controller,template:template,params:params,size:size}).result.then(result=>{"object"==typeof result&&this.getEstablecimientos()})}pagechanged(){this.getEstablecimientos()}changePageSize(){this.dataSearch.pageIndex=1,this.getEstablecimientos()}async askToCloseEstab(item){const swalWithBootstrapButtons=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger m-l-5"},buttonsStyling:!1}),{isConfirmed:isConfirmed}=await swalWithBootstrapButtons.fire({title:"Cerrar el Establecimiento",html:"<small>Esta seguro de cerrar el Establecimiento?</small>",icon:"warning",showCancelButton:!0,confirmButtonText:"Sí, cerrar!",cancelButtonText:"No, cancelar!",allowOutsideClick:!1,reverseButtons:!1});isConfirmed&&this._mS.getData("delete",`/Establecimiento/Delete?id=${item.idEstablecimiento}`).then(response=>{"0"===response.code&&this._tS.toastr("warning",response.message),"1"===response.code&&(this._tS.toastr("success",response.message),this.getEstablecimientos())})}}app.controller("establecimientoCtrl",EstablecimientoCtrl);